CREATE TRIGGER immutable_decisions_UPDATE BEFORE UPDATE ON decisions BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER immutable_decisions_DELETE BEFORE DELETE ON decisions BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER immutable_rule_allowances_UPDATE BEFORE UPDATE ON rule_allowances BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER immutable_rule_allowances_DELETE BEFORE DELETE ON rule_allowances BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER immutable_rule_identity BEFORE UPDATE OF id,subject_id,originating_decision_id ON policy_rules BEGIN SELECT RAISE(ABORT,'immutable rule identity'); END;
COMMIT;
PRAGMA user_version=1;
